# Maine Revised Statutes from legislature.maine.gov/statutes: every title's official .docx (one per title), split at the bold "§N." heading paragraphs.
import re, io, zipfile, time, html as _h
BASE = "https://legislature.maine.gov/statutes/"
STRUCT = re.compile(r"(TITLE|PART|CHAPTER|SUBCHAPTER|ARTICLE|SUBPART|DIVISION)\s+\S+$")
TODAY = time.strftime("%Y%m%d")

def _paras(xml):
    for p in re.findall(r"<w:p[ >].*?</w:p>", xml, re.S):
        p = re.sub(r"<w:(?:tab|br)\s*/>", " ", p)
        t = _h.unescape("".join(re.findall(r"<w:t(?: [^>]*)?>([^<]*)</w:t>", p))).replace("‑", "-")
        t = " ".join(t.split())
        if t:
            ppr = p.split("</w:pPr>")[0]
            yield t, 'w:val="center"' in ppr, "§" in p and "<w:b />" in p[:p.find("§")]

def _current(lines):
    """A section printed twice (text effective until a date, and the text effective from it): keep the one in force today."""
    m = re.search(r"\(WHOLE SECTION TEXT EFFECTIVE (UNTIL )?(\d+)/(\d+)/(\d+)\)", " ".join(lines[:3]))
    if not m:
        return True
    d = f"20{int(m.group(4)) % 100:02d}{int(m.group(2)):02d}{int(m.group(3)):02d}"
    return TODAY < d if m.group(1) else TODAY >= d

def _split(xml):
    cur = None
    for text, centered, bold in _paras(xml):
        m = re.match(r"§\s*([0-9][0-9A-Za-z-]*)\.\s*(.*)", text) if bold and not centered else None
        if m or (centered and STRUCT.match(text)):
            if cur and cur["lines"]:
                yield cur
            cur = {"id": m.group(1), "heading": m.group(2).strip(), "lines": []} if m else None
        elif cur is not None:
            cur["lines"].append(text)
    if cur and cur["lines"]:
        yield cur

def sections():
    _, idx = fetch(BASE)
    titles = []
    for t in re.findall(r'href="([0-9]+(?:-[A-Z])?)/title[0-9A-Z-]+ch0sec0\.html"', idx):
        if t not in titles:
            titles.append(t)
    log(f"{len(titles)} titles")
    for t in titles:
        url = f"{BASE}{t}/title{t}.docx"
        try:
            kind, raw = fetch(url)
            xml = zipfile.ZipFile(io.BytesIO(raw)).read("word/document.xml").decode("utf-8")
        except Exception as e:
            log(f"title {t} failed: {e}"); continue
        best, order, pend = {}, [], 0
        for s in _split(xml):
            if not _current(s["lines"]):
                pend += 1; continue
            old = best.get(s["id"])
            if old is None:
                best[s["id"]] = s; order.append(s["id"])
            elif old["lines"][0] == "(REPEALED)" and s["lines"][0] != "(REPEALED)":
                best[s["id"]] = s          # a number repealed in one chapter and reused in another: the live one
        for sid in order:
            s = best[sid]
            yield {"id": sid, "heading": s["heading"], "text": "\n".join(s["lines"]), "url": url, "vars": {"title": t}}
        log(f"title {t}: {len(order)} sections, {pend} pending versions left out")
